VALUES (5, $sample$Global Health Outcomes · Sample$sample$, $sample$Life expectancy, health spending and infant mortality for 45 countries, 2000-2022. Built on World Bank Open Data.$sample$, $sample$[{"id":"aca8caa7-c82c-5cea-83d3-ef4260a68a99","kind":"text","title":"About this sample","text":"## 🩺 Global Health Outcomes\nA **sample project** on the bundled `world_health_indicators` dataset — World Bank Open Data (CC-BY 4.0) for 45 countries, 2000–2022. The scatter is the classic spending-vs-longevity curve; the map shades life expectancy. Filter by region, or ask the AI analyst *“which countries get the most life expectancy per dollar?”*"},{"id":"49456a3e-7246-57a9-958a-ed7e0b402a50","kind":"chart","title":"Countries","source":{"kind":"local"},"sql":"SELECT COUNT(DISTINCT country) AS [Countries] FROM world_health_indicators","chart":{"type":"kpi","valueField":"Countries","label":"Countries tracked"},"columns":["Countries"],"rows":[{"Countries":45}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"tint","accent":"teal"}},{"id":"e54d9938-a9df-53ec-81bf-353802b99b47","kind":"chart","title":"Life expectancy","source":{"kind":"local"},"sql":"SELECT ROUND(AVG(life_expectancy),1) AS [Avg Life Expectancy] FROM world_health_indicators WHERE year = 2022","chart":{"type":"kpi","valueField":"Avg Life Expectancy","label":"Avg life expectancy · 2022"},"columns":["Avg Life Expectancy"],"rows":[{"Avg Life Expectancy":77.6}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"tint","accent":"emerald"}},{"id":"6d3a4909-46c3-54a9-b305-8c604cf938fb","kind":"chart","title":"Health spend","source":{"kind":"local"},"sql":"SELECT ROUND(AVG(health_spend_pct_gdp),1) AS [Health Spend] FROM world_health_indicators WHERE year = 2021","chart":{"type":"kpi","valueField":"Health Spend","label":"Avg health spend, % of GDP","format":"percent"},"columns":["Health Spend"],"rows":[{"Health Spend":8.5}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"tint","accent":"blue"}},