VALUES (6, $sample$Global Electricity Transition · Sample$sample$, $sample$The world's electricity mix 1990-2023 — coal to solar, country by country. Built on Our World in Data's energy dataset.$sample$, $sample$[{"id":"3cb609d8-f1f0-5082-8747-cb49882f8d67","kind":"text","title":"About this sample","text":"## ⚡ Global Electricity Transition\nA **sample project** on the bundled `global_electricity` dataset — Our World in Data's energy dataset (CC-BY 4.0): generation by source for the World and 28 countries, 1990–2023. The stacked area shows wind and solar bending the curve; the background is NASA's Solar Dynamics Observatory. Filter by country, or ask the AI analyst *“who decarbonised fastest since 2010?”*"},{"id":"b202502d-4ba1-5ad5-a47b-a351717d395b","kind":"chart","title":"World generation","source":{"kind":"local"},"sql":"SELECT total_twh AS [World Generation] FROM global_electricity WHERE country = 'World' AND year = 2023","chart":{"type":"kpi","valueField":"World Generation","label":"World generation 2023, TWh"},"columns":["World Generation"],"rows":[{"World Generation":29665.34}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"glass","accent":"amber"}},{"id":"1ab9fe93-9e82-541d-a86f-b516ef95c9c5","kind":"chart","title":"Renewables share","source":{"kind":"local"},"sql":"SELECT renewables_share_pct AS [Renewables Share] FROM global_electricity WHERE country = 'World' AND year = 2023","chart":{"type":"kpi","valueField":"Renewables Share","label":"Renewable share of electricity","format":"percent"},"columns":["Renewables Share"],"rows":[{"Renewables Share":30.3}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"glass","accent":"emerald"}},{"id":"cee10b4f-1ac9-5e73-974a-705122077f4c","kind":"chart","title":"Solar","source":{"kind":"local"},"sql":"SELECT ROUND(solar_twh,0) AS [Solar TWh] FROM global_electricity WHERE country = 'World' AND year = 2023","chart":{"type":"kpi","valueField":"Solar TWh","label":"Solar 2023, TWh (33x since 2010)"},"columns":["Solar TWh"],"rows":[{"Solar TWh":1664}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"glass","accent":"amber"}},{"id":"09809550-0bf7-5053-88cc-c32e28e0642f","kind":"chart","title":"Wind","source":{"kind":"local"},"sql":"SELECT ROUND(wind_twh,0) AS [Wind TWh] FROM global_electricity WHERE country = 'World' AND year = 2023","chart":{"type":"kpi","valueField":"Wind TWh","label":"Wind 2023, TWh"},"columns":["Wind TWh"],"rows":[{"Wind TWh":2319}],"refreshed_at":"2026-07-21T18:00:00.000Z","theme":{"card":"glass","accent":"teal"}},{"id":"523fbbf5-97bc-5eef-8110-20896b9f8f09","kind":"chart","title":"World electricity mix · 1990-2023","source":{"kind":"local"},"sql":"SELECT year AS [Year], country AS [Country], 'Coal' AS [Source], coal_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Gas' AS [Source], gas_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Oil' AS [Source], oil_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Nuclear' AS [Source], nuclear_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Hydro' AS [Source], hydro_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Solar' AS [Source], solar_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Wind' AS [Source], wind_twh AS [TWh] FROM global_electricity WHERE country = 'World' UNION ALL SELECT year AS [Year], country AS [Country], 'Other Renewables' AS [Source], other_renewables_twh AS [TWh] FROM global_electricity WHERE country = 'World' ORDER BY [Year]","chart":{"type":"area","xField":"Year","yField":"TWh","seriesField":"Source"},"columns":["Year","Country","Source","TWh"],"rows":[{"Year":1990,"Co